/* ══════════════════════════════════════════════════════════
   TECHYGUIDE — SCRATCH-INSPIRED DESIGN SYSTEM
   Bold, colorful, playful. Scratch 3.0 vibes.
   Neo-brutal edges. Strong affordances.
   ══════════════════════════════════════════════════════════ */

/* ── Design Tokens ─────────────────────────────────── */
:root {
  --bg-primary: #FFFFFF;
  --bg-secondary: #F9FAFB;
  --bg-tertiary: #ebebeb;

  /* Scratch-inspired palette */
  --scratch-blue: #4C97FF;
  --scratch-blue-dark: #3D8BF5;
  --scratch-blue-light: rgba(76, 151, 255, 0.15);
  --scratch-green: #4CAF50;
  --scratch-green-dark: #43A047;
  --scratch-orange: #FF8C1A;
  --scratch-orange-dark: #E67E00;
  --scratch-purple: #9966FF;
  --scratch-purple-dark: #855CD6;

  /* TechyGuide Brand Colors (kept for non-navbar UI) */
  --teal: #00897B;
  --teal-hover: #00796B;
  --teal-light: rgba(0, 137, 123, 0.08);
  --teal-surface: rgba(0, 137, 123, 0.12);

  --accent: #FF8C1A;
  --accent-hover: #E67E00;
  --accent-light: rgba(255, 140, 26, 0.12);
  --accent-surface: rgba(255, 140, 26, 0.14);

  /* Connected state */
  --connected: #4CAF50;
  --connected-light: rgba(76, 175, 80, 0.15);

  --text-primary: #111827;
  --text-secondary: #4B5563;
  --text-muted: #6B7280;
  
  --border: #E5E7EB;
  --border-strong: #D1D5DB;
  
  --header-bg: #4C97FF;
  --header-text: #FFFFFF;
  
  --code-bg: #0F172A;
  --code-gutter: #1E293B;
  
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 14px;
  
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.12);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.15);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.2);
  --shadow-brutal: 3px 3px 0px rgba(0,0,0,0.2);
  
  --font-mono: 'JetBrains Mono', 'Fira Code', 'SF Mono', monospace;
  --font-ui: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  --transition: 0.15s ease;
}

/* ── Reset & Base ──────────────────────────────────── */
*, *::before, *::after { box-sizing: border-box; }
.blocklySvg * { box-sizing: content-box; }

body {
  margin: 0;
  max-width: 100vw;
  font-family: var(--font-ui);
  background: var(--bg-primary);
  color: var(--text-primary);
  overflow: hidden;
  -webkit-font-smoothing: antialiased;
}

pre, code { overflow: auto; }

input:focus {
  outline: none;
  border-color: var(--scratch-blue) !important;
  box-shadow: 0 0 0 2px var(--scratch-blue-light) !important;
}

