                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 NAV BUTTONS — Stateful styles (Tailwind handles layout)
   ══════════════════════════════════════════════════════ */
.nav-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 0 16px;
  border-radius: 8px;
  font-size: 13px;
  font-weight: 700;
  font-family: var(--font-ui);
  cursor: pointer;
  border: none;
  background: transparent;
  color: #FFFFFF;
  transition: all 0.15s ease;
  white-space: nowrap;
  height: 40px;
  position: relative;
  letter-spacing: 0.2px;
}
.nav-btn:hover {
  background: rgba(255,255,255,0.15);
  transform: translateY(-1px);
}
.nav-btn:active {
  transform: scale(0.97) translateY(0);
  box-shadow: none;
}
.nav-btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
  pointer-events: none;
}
.nav-btn svg, .nav-btn i { flex-shrink: 0; color: #FFFFFF; }

/* ── Board Button (Orange) ── */
.nav-btn--board {
  background: transparent;
}
.nav-btn--board:hover {
  background: rgba(255,255,255,0.15);
}

/* ── Board Selection Modal (compact popup) ── */
.board-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 10000;
  background: rgba(0, 0, 0, 0.45);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.2s ease, visibility 0.2s ease;
}
.board-modal-overlay.open {
  opacity: 1;
  visibility: visible;
}

.board-modal-box {
  background: #fff;
  border-radius: 14px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.18);
  padding: 0;
  width: auto;
  max-width: 520px;
  overflow: hidden;
  transform: scale(0.95) translateY(8px);
  transition: transform 0.25s cubic-bezier(0.34, 1.2, 0.64, 1);
}
.board-modal-overlay.open .board-modal-box {
  transform: scale(1) translateY(0);
}

.board-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  border-bottom: 1px solid var(--border);
}

.board-modal-title {
  font-family: var(--font-ui);
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}

.board-modal-close {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  transition: all 0.15s ease;
}
.board-modal-close:hover {
  background: var(--bg-secondary);
  color: var(--text-primary);
}

.board-modal-cards {
  display: flex;
  gap: 16px;
  padding: 20px;
  justify-content: center;
}

.board-modal-card {
  width: 200px;
  background: var(--bg-secondary);
  border: 2px solid var(--border);
  border-radius: 12px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  align-items: center;
  overflow: hidden;
  transition: all 0.2s ease;
}
.board-modal-card:hover {
  border-color: var(--scratch-blue);
  box-shadow: 0 4px 16px rgba(76, 151, 255, 0.15);
  transform: translateY(-2px);
}
.board-modal-card.is-selected {
  border-color: var(--scratch-blue);
  background: var(--scratch-blue-light);
  box-shadow: 0 0 0 3px var(--scratch-blue-light);
}

.board-modal-card-img {
  width: 100%;
  height: 140px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  background: #fff;
  border-bottom: 1px solid var(--border);
}
.board-modal-card-img img {
  width: 100%;
  height: 100%;
  object-fit: contain;
  transform: scale(1.8);
  transition: transform 0.3s ease;
}
.board-modal-card:hover .board-modal-card-img img {
  transform: scale(1.95);
}

.board-modal-card-name {
  font-family: var(--font-ui);
  font-size: 14px;
  font-weight: 700;
  color: var(--text-primary);
  text-transform: capitalize;
  padding: 10px 0 12px;
}

/* ── Board Card States (legacy compat) ── */
.board-card.is-selected {
  border-color: var(--scratch-blue);
  background: var(--scratch-blue-light);
  box-shadow: 0 0 0 3px var(--scratch-blue-light);
}

/* ── Connect Button (Green) ── */
.nav-btn--connect {
  background: transparent;
}
.nav-btn--connect:hover {
  background: rgba(255,255,255,0.15);
}
.nav-btn--connect .status-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.5);
  flex-shrink: 0;
  transition: background 0.3s, box-shadow 0.3s;
}
.nav-btn--connect.is-connected {
  background: #388E3C;
  border-color: #2E7D32;
}
.nav-btn--connect.is-connected .status-dot {
  background: #A5D6A7;
  box-shadow: 0 0 8px rgba(165, 214, 167, 0.7);
}
.nav-btn--connect.is-connecting .status-dot {
  background: #FFF176;
  animation: pulse-dot 1.2s ease-in-out infinite;
}
@keyframes pulse-dot {
  0%, 100% { opacity: 1; }
  50%      { opacity: 0.3; }
}

/* ── Tab Active State ── */
.header-tab.active {
  background: #FFFFFF !important;
    color: #111827 !important;
  box-shadow: 0 1px 4px rgba(0,0,0,0.2);
}
.header-tab:hover:not(.active) {
  color: #111827;
  background: rgba(0, 0, 0, 0.05);
}

/* ── Upload Button (Orange) ── */
.nav-btn--upload {
  background: var(--scratch-orange);
  border-color: var(--scratch-orange-dark);
  font-weight: 700;
  gap: 6px;
  box-shadow: var(--shadow-brutal);
}
.nav-btn--upload:hover {
  background: var(--scratch-orange-dark);
  border-color: var(--scratch-orange-dark);
  box-shadow: 0 3px 10px rgba(255,140,26,0.35);
}

/* ── Tooltip ── */
[data-tooltip] { position: relative; }
[data-tooltip]::after {
  content: attr(data-tooltip);
  position: absolute;
  bottom: -32px;
  left: 50%;
  transform: translateX(-50%) translateY(4px);
  background: #1E293B;
  color: #F8FAFC;
  font-size: 11px;
  font-weight: 500;
  padding: 4px 10px;
  border-radius: 6px;
  white-space: nowrap;
  opacity: 0;
  pointer-events: none;
  transition: all 0.2s ease;
  z-index: 500;
}
[data-tooltip]:hover::after {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
}

/* ── Mode Dropdown (kept as fallback) ──────────────── */
.mode-dropdown-wrap { position: relative; display: none; }
.mode-dropdown {
  appearance: none;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: var(--radius-sm);
  color: var(--header-text);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  padding: 6px 32px 6px 12px;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  background-image: url("data:image/svg+xml,%3Csvg width='10' height='6' viewBox='0 0 10 6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1 1l4 4 4-4' stroke='%2394a3b8' stroke-width='1.5' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E");
  background-repeat: no-repeat;
  background-position: right 10px center;
}

/* ── Scratch Controls (Green Flag / Stop) ──────────── */
.scratch-controls {
  display: flex;
  align-items: center;
  gap: 4px;
  position: absolute;
  left: 16px;
  top: 8px;
  z-index: 50;
}

#stageContainer { position: relative; }

.control-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  cursor: pointer;
  transition: all var(--transition);
}
.control-btn:hover { background: var(--bg-secondary); }
.flag-btn:hover { border-color: #4CAF50; }
.stop-btn:hover { border-color: var(--accent); }

/* ── Main Layout ───────────────────────────────────── */
#pageContainer {
  display: flex;
  width: 100%;
  max-width: 100vw;
  height: calc(100vh - 64px);
  position: relative;
    overflow: hidden;
}

#blocklyDiv {
  flex: 1 1 auto;
  height: 100%;
  min-width: 0;
  background: var(--bg-primary);
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }
  
  .pane-toggle-btn {
    position: absolute;
    top: 50%;
    right: 480px;
    transform: translateY(-50%) translateX(50%);
    width: 24px;
    height: 48px;
    background: #fff;
    border: 1px solid var(--border);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    z-index: 50;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.1);
    transition: right 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    color: var(--text-secondary);
  }
  
  .pane-toggle-btn:hover {
    background: var(--bg-secondary);
    color: var(--text-primary);
  }
  
  .pane-toggle-btn svg {
    transition: transform 0.3s ease;
  }
  
  .pane-toggle-btn.is-collapsed svg {
    transform: rotate(180deg);
  }
  
  .pane-toggle-btn.is-collapsed {
    right: 0px;
    transform: translateY(-50%) translateX(0%);
    border-right: none;
    border-top-right-radius: 0;
    border-bottom-right-radius: 0;
}

/* ── Right Pane (shared) ───────────────────────────── */
.right-pane {
  display: flex;
  flex-direction: column;
  width: 480px;
  flex: 0 0 480px;
  background: var(--bg-primary);
  border-left: 1px solid var(--border);
  transition: width 0.3s cubic-bezier(0.4, 0, 0.2, 1), flex-basis 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
  }
  
  .right-pane.is-hidden {
    width: 0px;
    flex-basis: 0px;
    border-left: none;
}

/* ── Stage Area ──────────────────────────────────── */
#scratchPane { gap: 0; }

#stageContainer {
  background: var(--bg-primary);
  border-bottom: 1px solid var(--border);
  overflow: hidden;
  height: 360px;
  position: relative;
  line-height: 0;
}

#stageCanvas {
  width: 480px;
  height: 360px;
  display: block;
}

/* ── Sprite Panel ────────────────────────────────── */
#spritePanelContainer {
  display: flex;
  flex-direction: column;
  background: var(--bg-secondary);
  padding: 10px;
  gap: 10px;
  flex: 1;
}

.sprite-info-bar {
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  padding: 8px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  font-size: 11px;
  color: var(--text-secondary);
  font-weight: 500;
}

.info-row {
  display: flex;
  gap: 12px;
  align-items: center;
}

.info-group {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sprite-name-group input {
  width: 90px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px 8px;
  font-size: 11px;
  font-family: var(--font-ui);
}

.xy-group {
  display: flex;
  gap: 8px;
  margin-left: auto;
}
.xy-group label {
  display: flex;
  align-items: center;
  gap: 4px;
}
.xy-group input, .size-group input, .direction-group input {
  width: 52px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  padding: 4px 6px;
  text-align: center;
  font-size: 11px;
  font-family: var(--font-ui);
  box-sizing: border-box;
  -moz-appearance: textfield;
  appearance: textfield;
}
.xy-group input::-webkit-inner-spin-button,
.xy-group input::-webkit-outer-spin-button,
.size-group input::-webkit-inner-spin-button,
.size-group input::-webkit-outer-spin-button,
.direction-group input::-webkit-inner-spin-button,
.direction-group input::-webkit-outer-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.toggle-btns {
  display: flex;
  gap: 4px;
}
.icon-btn {
  width: 28px;
  height: 28px;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  cursor: pointer;
  color: var(--text-secondary);
  display: flex; align-items: center; justify-content: center;
  transition: all var(--transition);
}
.icon-btn.active {
  background: var(--accent);
  border-color: var(--accent);
  color: white;
}

/* ── Lists Area ── */
.media-lists-area {
  display: flex;
  gap: 10px;
  height: 160px;
}

.sprite-list-section {
  flex: 1;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  position: relative;
  display: flex;
}

.media-list {
  flex: 1;
  padding: 10px;
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  overflow-y: auto;
  align-content: flex-start;
}

.stage-list-section {
  width: 80px;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  border-radius: var(--radius-md);
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 8px 0;
  position: relative;
}

.stage-header {
  font-size: 11px;
  color: var(--text-secondary);
  text-align: center;
  margin-bottom: 8px;
  font-weight: bold;
}
.stage-header small { font-weight: normal; font-size: 9px; }

/* ── Thumbnails ── */
.sprite-thumb {
  width: 70px;
  height: 80px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  display: flex;
  flex-direction: column;
  position: relative;
  overflow: hidden;
  transition: border-color var(--transition);
}
.sprite-thumb:hover { border-color: var(--accent); }
.sprite-thumb.selected {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-light);
}

.sprite-thumb img {
  width: 40px;
  height: 40px;
  margin: 10px auto 4px;
  object-fit: contain;
}

.sprite-thumb-info {
  background: var(--bg-tertiary);
  width: 100%;
  text-align: center;
  padding: 4px 0;
  margin-top: auto;
}
.sprite-thumb.selected .sprite-thumb-info {
  background: var(--accent-surface);
  color: var(--accent);
}

.sprite-thumb-name { font-size: 10px; font-weight: 600; }

.delete-btn {
  position: absolute;
  top: -4px; right: -4px;
  width: 20px; height: 20px;
  background: var(--accent);
  color: white;
  border-radius: 50%;
  display: none;
  align-items: center; justify-content: center;
  font-size: 14px; font-weight: bold;
}
.sprite-thumb:hover .delete-btn { display: flex; }

.backdrop-thumb {
  width: 50px; height: 40px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  box-shadow: 0 0 0 3px var(--accent-light);
}

/* ── FAB Add Buttons ── */
.fab-btn {
  position: absolute;
  bottom: -15px;
  right: -5px;
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: none;
  background: var(--accent);
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  box-shadow: var(--shadow-md);
  transition: transform 0.1s;
  z-index: 10;
}
.fab-btn:hover { transform: scale(1.1); background: var(--accent-hover); }
.add-backdrop-fab { background: var(--text-primary); bottom: -15px; left: 20px; }


/* ── Blockly Overrides ── */
.blocklyToolboxCategoryContainer {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  width: 100%;
}

.blocklyToolboxCategory {
  border: none !important;
  padding: 0 !important;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  height: auto !important;
  width: 100%;
  background: none !important;
}

.blocklyToolboxCategoryGroup {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  margin: 20px 0;
  gap: 50px;
}

.blocklyToolboxCategoryIcon { display: none !important; }

/* Hide persistent scrollbars from Flyout */
.blocklyScrollbarBackground,
.blocklyScrollbarHandle,
.blocklyFlyoutScrollbar {
  display: none !important;
  opacity: 0 !important;
}
#color-1 { background: #4c97ff; }
#color-2 { background: #9966ff; }
#color-3 { background: #cf63cf; }
#color-4 { background: #ffbf00; }
#color-5 { background: #ffab19; }
#color-6 { background: #5cb1d6; }
#color-7 { background: #59c059; }
#color-8 { background: #ff8c1a; }
#color-9 { background: #00a69c; }
#color-10 { background: var(--scratch-blue); }

/* ── ESP32 Subcategory Labels ── */
.esp32-subcategory-label .blocklyFlyoutLabelText {
  font-size: 12px !important;
  font-weight: 800 !important;
  fill: var(--scratch-blue) !important;
  text-transform: uppercase;
  letter-spacing: 1px;
  paint-order: stroke fill !important;
  stroke: var(--bg-primary) !important;
  stroke-width: 5px !important;
  stroke-linecap: round !important;
  stroke-linejoin: round !important;
  transform: translateX(8px);
}

/* ── ESP32 Category Divider ── */
.blocklyFlyoutLabel.esp32-subcategory-label {
  border-left: 4px solid var(--scratch-blue) !important;
  margin: 12px 0 6px 12px !important;
  padding-left: 10px !important;
}

[id^="color-"] {
  width: 30px;
  height: 30px;
  border-radius: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 5px 0;
  pointer-events: none;
}

.blocklyTreeSeparator { display: none !important; }

/* ── ESP32 Block Styling Overrides ─────────────────── */
.blocklyDraggable .blocklyEditableText rect {
  rx: 4 !important;
  ry: 4 !important;
  stroke: rgba(0,0,0,0.1) !important;
  stroke-width: 1 !important;
}

.blocklyDropDownDiv .blocklyMenu {
  font-family: var(--font-ui) !important;
  font-size: 13px !important;
  border-radius: 8px !important;
}

/* ══════════════════════════════════════════════════════
   BOARD PANE — CODE EDITOR
   ══════════════════════════════════════════════════════ */
#boardPane {
  background: var(--code-bg);
  gap: 0;
  flex-direction: column;
  }
  
  /* ── Board Sub-views ── */
  .board-subview {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
  }
  
  #boardStageView {
    background: var(--bg-primary);
    align-items: stretch;
    justify-content: flex-start;
    overflow: auto;
  }
  
  #boardStageSlot {
    display: flex;
    flex-direction: column;
    flex: 1;
  }
  
  #boardStageSlot #stageContainer {
    width: 100%;
    height: 360px;
    border-bottom: 1px solid var(--border);
  }
  
/* ── 2. Code Editor Panel ── */
.editor-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background-color: var(--code-bg);
  padding: 0 12px;
  flex-shrink: 0;
}

.file-tab {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--font-mono);
  font-size: 12px;
  color: #FFFFFF;
  background-color: transparent;
  height: 100%;
  padding: 0 16px;
  border-bottom: 2px solid var(--accent);
}

.env-dropdown {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.2);
  color: #FFFFFF;
  font-size: 12px;
  padding: 2px 6px;
  border-radius: 0;
  outline: none;
}

.editor-footer {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  height: 40px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  padding: 0 12px;
  background-color: var(--code-bg);
  flex-shrink: 0;
}

.toolbar-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  background: transparent;
  border: 1px solid transparent;
  color: #E5E7EB;
  font-size: 12px;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 0;
  cursor: pointer;
  transition: all 0.2s;
}

.toolbar-btn svg {
  width: 14px;
  height: 14px;
  color: currentColor;
}


.toolbar-btn:hover {
  background-color: rgba(255, 255, 255, 0.05);
}

#uploadBtn {
  background-color: var(--accent);
  color: #FFFFFF;
}

#uploadBtn:hover {
  background-color: var(--accent-hover);
}

#boardCodeView {
  background-color: var(--code-bg);
}

/* ══════════════════════════════════════════════════════
   SERIAL MONITOR
   ══════════════════════════════════════════════════════ */
#serialMonitorContainer {
  flex-shrink: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.sm-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 36px;
  padding: 0 10px;
  background: #0D1525;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  gap: 8px;
}

.sm-toolbar-left {
  display: flex;
  align-items: center;
}

.sm-toolbar-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.sm-btn {
  display: flex;
  align-items: center;
  gap: 5px;
  background: transparent;
  border: none;
  color: #94A3B8;
  font-size: 12px;
  font-family: var(--font-primary);
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 4px;
  transition: all 0.15s;
  white-space: nowrap;
}

.sm-btn:hover {
  color: #E2E8F0;
  background: rgba(255, 255, 255, 0.06);
}

.sm-toggle-btn {
  font-weight: 600;
  color: #CBD5E1;
  gap: 6px;
}

.sm-toggle-btn:hover {
  color: #F1F5F9;
}

.sm-chevron {
  transition: transform 0.2s ease;
  opacity: 0.5;
}

.sm-icon-btn {
  padding: 4px 6px;
}

.sm-connect-btn {
  background: rgba(76, 175, 80, 0.12);
  color: #4CAF50;
  border: 1px solid rgba(76, 175, 80, 0.25);
  font-weight: 500;
}

.sm-connect-btn:hover {
  background: rgba(76, 175, 80, 0.2);
  color: #66BB6A;
}

.sm-connect-btn.sm-connected {
  background: rgba(239, 68, 68, 0.12);
  color: #EF4444;
  border-color: rgba(239, 68, 68, 0.25);
}

.sm-connect-btn.sm-connected:hover {
  background: rgba(239, 68, 68, 0.2);
  color: #F87171;
}

.sm-baud-select,
.sm-ending-select {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: #94A3B8;
  font-size: 11px;
  font-family: var(--font-mono);
  padding: 3px 6px;
  border-radius: 4px;
  outline: none;
  cursor: pointer;
}

.sm-baud-select:hover,
.sm-ending-select:hover {
  border-color: rgba(255, 255, 255, 0.25);
}

.sm-baud-select option,
.sm-ending-select option {
  background: #1E293B;
  color: #E2E8F0;
}

.sm-autoscroll-label {
  display: flex;
  align-items: center;
  gap: 4px;
  color: #64748B;
  font-size: 11px;
  cursor: pointer;
  user-select: none;
}

.sm-autoscroll-label input[type="checkbox"] {
  width: 13px;
  height: 13px;
  accent-color: var(--scratch-blue);
  cursor: pointer;
}

.sm-autoscroll-label:hover {
  color: #94A3B8;
}

/* ── Serial Output Terminal ── */
.sm-body {
  display: flex;
  flex-direction: column;
  height: 200px;
  background: #0A0F1A;
}

.sm-output {
  flex: 1;
  overflow-y: auto;
  overflow-x: hidden;
  padding: 8px 12px;
  font-family: var(--font-mono);
  font-size: 12px;
  line-height: 1.6;
  color: #E2E8F0;
  white-space: pre-wrap;
  word-break: break-all;
}

.sm-output::-webkit-scrollbar {
  width: 6px;
}

.sm-output::-webkit-scrollbar-track {
  background: transparent;
}

.sm-output::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 3px;
}

.sm-output::-webkit-scrollbar-thumb:hover {
  background: rgba(255, 255, 255, 0.2);
}

/* Output color coding */
.sm-system {
  color: #64748B;
  font-style: italic;
}

.sm-error {
  color: #F87171;
}

.sm-sent {
  color: #60A5FA;
}

/* ── Serial Input Bar ── */
.sm-input-bar {
  display: flex;
  align-items: center;
  gap: 0;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
  background: #0D1525;
  flex-shrink: 0;
}

.sm-input {
  flex: 1;
  background: transparent;
  border: none;
  color: #E2E8F0;
  font-family: var(--font-mono);
  font-size: 12px;
  padding: 8px 12px;
  outline: none;
}

.sm-input::placeholder {
  color: #475569;
}

.sm-input:disabled {
  opacity: 0.4;
}

.sm-send-btn {
  padding: 8px 12px;
  border-left: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 0;
  color: var(--scratch-blue);
}

.sm-send-btn:hover:not(:disabled) {
  background: rgba(76, 151, 255, 0.1);
}

.sm-send-btn:disabled {
  opacity: 0.3;
  cursor: not-allowed;
}
/* ── Code Editor Body (gutter + textarea) ── */
.code-editor-body {
  flex: 1;
  display: flex;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.6;
  min-height: 0;
    position: relative;
}

.code-gutter {
  flex: 0 0 44px;
  background: var(--code-gutter);
  color: #64748B;
  text-align: right;
  padding: 10px 8px 10px 0;
  user-select: none;
  font-size: 12px;
  line-height: 1.6;
  overflow: hidden;
}
.code-gutter div {
  height: 1.6em;
}

/* Editable code textarea */
.code-textarea {
  flex: 1;
  padding: 10px 16px;
  color: #cdd6f4;
  background: transparent;
  border: none;
  outline: none;
  resize: none;
  font-family: var(--font-mono);
  font-size: 13px;
  line-height: 1.6;
  white-space: pre;
  overflow: auto;
  tab-size: 2;
  caret-color: var(--accent);
  -webkit-text-fill-color: #cdd6f4;
}

.code-textarea::placeholder {
  color: #444;
  -webkit-text-fill-color: #444;
}

.code-textarea:focus {
  outline: none;
}

/* Selection styling inside textarea */
.code-textarea::selection {
  background: rgba(194, 65, 12, 0.3);
}

/* Deprecated but kept for backwards compat — the old div-based code view */
.code-content {
  flex: 1;
  padding: 10px 16px;
  color: #cdd6f4;
  white-space: pre;
  overflow-x: auto;
}

/* ── Python Syntax Highlighting (kept for future overlay use) ── */
.py-keyword { color: #c678dd; font-weight: 600; }
.py-builtin { color: #e5c07b; }
.py-string  { color: #98c379; }
.py-comment { color: #5c6370; font-style: italic; }
.py-number  { color: #d19a66; }
.py-func    { color: #61afef; }
.py-decorator { color: #e06c75; }
.py-operator { color: #56b6c2; }

/* ── Code Editor Buttons ── */
.code-editor-actions {
  display: flex;
  gap: 8px;
  padding: 10px 12px;
  background: #16162a;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-shrink: 0;
}

.code-action-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  flex: 1;
  padding: 10px 16px;
  border: none;
  border-radius: var(--radius-sm);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all var(--transition);
}

.code-action-btn--primary {
  background: var(--accent);
  color: #fff;
}
.code-action-btn--primary:hover {
  background: var(--accent-hover);
}

.code-action-btn--secondary {
  background: rgba(255,255,255,0.06);
  color: #ccc;
  border: 1px solid rgba(255,255,255,0.1);
}
.code-action-btn--secondary:hover {
  background: rgba(255,255,255,0.1);
  color: #fff;
}

.code-action-btn svg { width: 14px; height: 14px; }

/* ── Upload Panel ────────────────────────────────────── */
#uploadPanel { flex: 0 0 auto; padding: 0 10px 14px; }
.upload-panel { background: #16162a; border: 1px solid rgba(255,255,255,0.08); border-radius: var(--radius-md); padding: 14px; display: flex; flex-direction: column; gap: 10px; }
.upload-header { display: flex; justify-content: space-between; }
.upload-title { font-size: 13px; font-weight: 700; color: #e2e8f0; display: flex; gap: 6px; }
.upload-status { font-size: 10px; font-weight: 700; padding: 3px 8px; border-radius: var(--radius-sm); }
.status-idle      { background: #1e293b; color: #64748b; }
.status-waiting   { background: #1e3a5f; color: #60a5fa; }
.status-uploading { background: #1a3a1a; color: #4ade80; animation: pulse 1s infinite; }
.status-success   { background: #14532d; color: #86efac; }
.status-error     { background: #3d1a00; color: var(--accent); }
@keyframes pulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.5; } }
.upload-btn { background: var(--accent); color: #fff; border: none; border-radius: var(--radius-sm); padding: 10px 16px; font-weight: 700; cursor: pointer; text-transform: uppercase; letter-spacing: 0.5px; font-family: var(--font-ui); }
.upload-btn:hover:not(:disabled) { background: var(--accent-hover); }
.upload-btn:disabled { background: #334155; color: #64748b; }

.pane-section-label { display: none; }
#generatedCode {
  display: none;
}

/* ── Backdrop Preview ────────────────────────── */
.backdrop-preview {
  width: 100%;
  height: 100%;
  border-radius: 2px;
  background: var(--bg-primary);
}

/* ══════════════════════════════════════════════════════
   MODAL SYSTEM — Shared
   ══════════════════════════════════════════════════════ */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s ease;
}
.modal-overlay.open {
  opacity: 1;
  pointer-events: auto;
}
.modal-overlay.open .modal-content {
  transform: scale(1) translateY(0);
}

.modal-content {
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  width: 520px;
  max-height: 520px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: scale(0.95) translateY(10px);
  transition: transform 0.2s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px;
  border-bottom: 2px solid var(--border);
}
.modal-header h3 {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
  letter-spacing: -0.3px;
}
.modal-close {
  width: 30px;
  height: 30px;
  border: 1px solid var(--border);
  background: var(--bg-secondary);
  border-radius: var(--radius-sm);
  font-size: 16px;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.modal-close:hover { background: var(--border); }

.modal-tabs {
  display: flex;
  border-bottom: 2px solid var(--border);
}
.modal-tab {
  padding: 10px 20px;
  border: none;
  background: none;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  margin-bottom: -2px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all var(--transition);
}
.modal-tab:hover { color: var(--text-secondary); }
.modal-tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.modal-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
}

.modal-footer {
  padding: 14px 20px;
  border-top: 2px solid var(--border);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
}
.modal-footer-text {
  font-size: 11px;
  color: var(--text-muted);
  font-weight: 500;
}

/* ── Connect Modal: Port List ── */
.port-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.port-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-family: var(--font-mono);
  font-size: 12px;
  color: var(--text-primary);
  transition: all var(--transition);
}
.port-item:hover {
  border-color: var(--accent);
  background: var(--accent-light);
}

.port-connect-btn {
  padding: 4px 14px;
  border: 1px solid var(--accent);
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--accent);
  font-family: var(--font-ui);
  font-size: 11px;
  font-weight: 700;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all var(--transition);
}
.port-connect-btn:hover {
  background: var(--accent);
  color: #fff;
}

.port-empty-state {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 160px;
  color: var(--text-muted);
  font-size: 13px;
  font-weight: 500;
}

/* ── Connection Status Indicator ── */
.connection-status {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 4px 10px;
  border-radius: var(--radius-sm);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
.status--disconnected {
  background: var(--bg-secondary);
  color: var(--text-muted);
}
.status--connecting {
  background: var(--accent-light);
  color: var(--accent);
  animation: pulse 1.5s infinite;
}
.status--connected {
  background: var(--connected-light);
  color: var(--connected);
}
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

/* ── Header Button Connected State ── */
.header-btn--connected {
  background: var(--teal) !important;
  border-color: var(--teal) !important;
  color: #fff !important;
}
.header-btn--connected:hover {
  background: var(--teal-hover) !important;
}

/* ── Port Item Connected ── */
.port-connect-btn--connected {
  background: var(--teal) !important;
  border-color: var(--teal) !important;
  color: #fff !important;
  cursor: default;
}

/* ── Pagination Dots ── */
.pagination-dots {
  display: flex;
  gap: 6px;
}
.pagination-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--border);
}
.pagination-dot.active {
  background: var(--accent);
}

/* ── Refresh Button ── */
.refresh-btn {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 8px 20px;
  border: 2px solid var(--text-primary);
  border-radius: var(--radius-sm);
  background: var(--bg-primary);
  color: var(--text-primary);
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all var(--transition);
}
.refresh-btn:hover {
  background: var(--text-primary);
  color: var(--bg-primary);
}
.refresh-btn svg { width: 14px; height: 14px; }



/* ══════════════════════════════════════════════════════
   CHOOSER MODAL (Sprite/Backdrop — existing, restyled)
   ══════════════════════════════════════════════════════ */
.chooser-overlay {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s ease;
}
.chooser-overlay.open { opacity: 1; }
.chooser-overlay.open .chooser-modal {
  transform: scale(1) translateY(0);
}

.chooser-modal {
  background: var(--bg-primary);
  border-radius: var(--radius-lg);
  width: 520px;
  max-height: 480px;
  box-shadow: var(--shadow-lg);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  transform: scale(0.95) translateY(10px);
  transition: transform 0.2s cubic-bezier(0.34, 1.2, 0.64, 1);
}

.chooser-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 20px 12px;
  border-bottom: 2px solid var(--border);
}
.chooser-header h3 {
  margin: 0;
  font-size: 15px;
  font-weight: 700;
  color: var(--text-primary);
}
.chooser-close {
  width: 30px;
  height: 30px;
  border: 1px solid var(--border);
  background: var(--bg-secondary);
  border-radius: var(--radius-sm);
  font-size: 16px;
  color: var(--text-secondary);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all var(--transition);
}
.chooser-close:hover { background: var(--border); }

.chooser-tabs {
  display: flex;
  gap: 0;
  padding: 0 20px;
  border-bottom: 2px solid var(--border);
}
.chooser-tab {
  padding: 10px 20px;
  border: none;
  background: none;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
  cursor: pointer;
  border-bottom: 2px solid transparent;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  transition: all var(--transition);
}
.chooser-tab:hover { color: var(--text-secondary); }
.chooser-tab.active {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.chooser-body {
  flex: 1;
  overflow-y: auto;
  padding: 16px 20px;
}

.chooser-category {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 8px;
  margin-top: 12px;
}
.chooser-category:first-child { margin-top: 0; }

.chooser-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  margin-bottom: 16px;
}
.backdrop-grid {
  grid-template-columns: repeat(3, 1fr);
}

.chooser-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  padding: 10px 6px 8px;
  border: 2px solid var(--border);
  border-radius: var(--radius-md);
  cursor: pointer;
  transition: all var(--transition);
  background: var(--bg-primary);
}
.chooser-item:hover {
  border-color: var(--accent);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(211, 84, 0, 0.1);
}
.chooser-item.active {
  border-color: var(--accent);
  background: var(--accent-light);
}

.chooser-item img {
  width: 56px;
  height: 56px;
  object-fit: contain;
}
.chooser-item span {
  font-size: 11px;
  font-weight: 600;
  color: var(--text-secondary);
  text-align: center;
}

.backdrop-preview-thumb {
  width: 100%;
  height: 70px;
  border-radius: var(--radius-md);
  border: 1px solid var(--border);
}

.chooser-upload-area {
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 240px;
}

.upload-dropzone {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  padding: 40px;
  border: 2px dashed var(--border);
  border-radius: var(--radius-lg);
  text-align: center;
  transition: all 0.2s;
  width: 100%;
}
.upload-dropzone.drag-over {
  border-color: var(--accent);
  background: var(--accent-light);
}
.upload-dropzone p {
  margin: 0;
  font-size: 14px;
  color: var(--text-secondary);
}
.upload-hint {
  font-size: 12px !important;
  color: var(--text-muted) !important;
}

.upload-browse-btn {
  display: inline-block;
  padding: 8px 20px;
  background: var(--accent);
  color: white;
  border-radius: var(--radius-sm);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--transition);
}
.upload-browse-btn:hover { background: var(--accent-hover); }
